// Embedded anti-aliased bitmap fonts (generated by tools/gen_font.py).
#pragma once
#include <cstdint>
#include <string>
#include <vector>

#include "gfx/canvas.h"

struct GlyphInfo {
    uint32_t cp;    // unicode code point
    uint32_t off;   // offset into the bitmap
    uint8_t w, h;   // bitmap size
    int8_t xo, yo;  // offset from pen position / baseline
    uint8_t adv;    // horizontal advance
};

struct FontData {
    int size;
    int ascent;
    int lineHeight;
    int count;
    const GlyphInfo* glyphs;
    const uint8_t* bits;
};

extern const FontData FONT_XS, FONT_SM, FONT_SMB, FONT_MD, FONT_MDB, FONT_LG, FONT_XL;
// The Lazaxian alphabet (0.57.0, the owner's font): only ! " ' ( ) , - . 0-9 ? A-Z a-z and the space.
extern const FontData FONT_LAZ;

enum class Align { Left, Center, Right };

// Text is UTF-8. (x, y) is the top-left of the line box.
int textWidth(const FontData& f, const std::string& s);
int drawText(Canvas& c, const FontData& f, int x, int y, const std::string& s, uint32_t color, int alpha = 255);
int drawTextAligned(Canvas& c, const FontData& f, int x, int y, int w, Align al, const std::string& s,
                    uint32_t color, int alpha = 255);
// Drop shadow for text over busy backgrounds (the galaxy map).
int drawTextShadow(Canvas& c, const FontData& f, int x, int y, const std::string& s, uint32_t color,
                   uint32_t shadow = 0);
// While one of these lives, all text gets a dark halo (0.20.0: text on the
// see-through side panel stays readable over the map running under it).
struct TextHalo {
    explicit TextHalo(int alpha = 150);
    ~TextHalo();
    TextHalo(const TextHalo&) = delete;
    TextHalo& operator=(const TextHalo&) = delete;

private:
    int prev_;
};
// Greedy word wrap into lines no wider than maxW.
std::vector<std::string> wrapText(const FontData& f, const std::string& s, int maxW);
// Shorten with an ellipsis so the text fits in maxW.
std::string fitText(const FontData& f, const std::string& s, int maxW);
